changeSet.rollback:

if exists (select * from [INFORMATION_SCHEMA].[COLUMNS] where TABLE_SCHEMA = 'dbo' and TABLE_NAME = 'Rule' and COLUMN_NAME = 'Color')
begin
	alter table [dbo].[Rule] drop column [Color]
end

if not exists (select * from [INFORMATION_SCHEMA].[COLUMNS] where TABLE_SCHEMA = 'dbo' and TABLE_NAME = 'Rule' and COLUMN_NAME = 'Color')
begin
	alter table [dbo].[Rule] add [Threshold] [decimal](4, 3) NULL;
	ALTER TABLE [dbo].[Rule] ADD  CONSTRAINT [DF_Rule_Threshold]  DEFAULT ((0)) FOR [Threshold];
end
